// cmd_famask: apply a X-coded FASTA to a source FASTA.
//
// Behavior pinned down from the reference binary:
//  - usage: "Usage: seqtk famask <src.fa> <mask.fa>" (stderr, exit 1)
//  - getopt with an empty optstring; unknown options print glibc's
//    "famask: invalid option -- 'c'" and are otherwise ignored
//  - reads both files in lockstep; the mask read's return value is ignored
//  - per record pair:
//      * if mask never yielded any record, the reference dereferences a
//        NULL mask name and dies with SIGSEGV (replicated via raise)
//      * name mismatch: "[stk_famask] Different sequence names: %s != %s\n"
//        (src name first) on stderr; masking is still applied
//      * length mismatch: "[stk_famask] Unequal sequence length: %d != %d\n"
//        (src first) on stderr; src is truncated to the mask length when
//        the mask is shorter
//      * mask char 'x': src base lowercased; 'X': src base kept as is;
//        anything else: src base replaced by the mask char
//  - output: '>' + src name only (comments dropped), sequence wrapped at
//    60 chars; an empty sequence prints no sequence line at all
//  - on mask EOF the mask keeps its previous name but its length becomes 0
//  - unopenable file: "[E::stk_famask] failed to open the input file/stream."
//    (stderr, exit 1)
//
// SeqFile cannot be used directly because the reference reader (kseq)
// differs in three observable ways: junk before the first record is skipped
// up to the first '>'/'@', a FASTQ record whose quality is shorter than its
// sequence at EOF is dropped (read error, record name/seq still visible),
// and after a read error the mask's name/length handling follows kseq's
// reset rules. KseqLite below replicates those semantics.

#include "common.h"
#include <unistd.h>
#include <csignal>
#include <cctype>
#include <cstdio>
#include <cstring>

namespace {

struct KseqLite {
    gzFile fp;
    int last_char = 0;      // 0: need to search for the next header char
    bool has_name = false;  // false emulates kseq's initially NULL name
    std::string name, comment, seq, qual;

    explicit KseqLite(const char* path) : fp(seqtk_gzopen(path)) {}
    ~KseqLite() { if (fp) gzclose(fp); }
    bool is_open() const { return fp != nullptr; }

    // Read one line without '\n'; trailing '\r' stripped.
    // Returns false only when EOF is hit with nothing read.
    bool read_line(std::string& out) {
        out.clear();
        int c;
        bool any = false;
        while ((c = gzgetc(fp)) >= 0) {
            any = true;
            if (c == '\n') break;
            out.push_back((char)c);
        }
        if (!any) return false;
        if (!out.empty() && out.back() == '\r') out.pop_back();
        return true;
    }

    // Returns 1 on record, -1 on EOF, -2 on short-quality FASTQ record.
    int read() {
        int c;
        if (last_char == 0) { // jump to the next header line
            while ((c = gzgetc(fp)) >= 0 && c != '>' && c != '@');
            if (c < 0) return -1; // EOF before any header: nothing reset
            last_char = c;
        }
        // kseq resets comment/seq/qual but keeps the previous name
        comment.clear();
        seq.clear();
        qual.clear();
        std::string line;
        if (!read_line(line)) return -1; // EOF right after '>'/'@'
        size_t i = 0;
        while (i < line.size() && !isspace((unsigned char)line[i])) ++i;
        name = line.substr(0, i);
        has_name = true;
        if (i < line.size()) comment = line.substr(i + 1);
        for (;;) {
            c = gzgetc(fp);
            if (c < 0) return 1; // EOF: complete record, last_char stays
            if (c == '>') { last_char = c; return 1; }
            if (c == '@') { last_char = c; return 1; }
            if (c == '+') { // quality follows
                read_line(line); // discard the '+' line
                while (qual.size() < seq.size()) {
                    if (!read_line(line)) {
                        // quality shorter than sequence at EOF: error;
                        // next read takes the header-search branch and
                        // fails at EOF without resetting the members
                        last_char = 0;
                        return -2;
                    }
                    qual += line;
                }
                last_char = 0; // after quality, search for the next header
                return 1;
            }
            ungetc_wrapper(c);
            if (!read_line(line)) return 1;
            seq += line;
        }
    }

    void ungetc_wrapper(int c) { pushback_ = c; }
    int pushback_ = -2;
    // gzgetc with one-char pushback
    int getc() {
        if (pushback_ != -2) { int c = pushback_; pushback_ = -2; return c; }
        return gzgetc(fp);
    }
};

} // namespace

int cmd_famask(int argc, char* argv[]) {
    int c;
    while ((c = getopt(argc, argv, "")) >= 0) (void)c; // no options
    if (argc - optind < 2) {
        fprintf(stderr, "Usage: seqtk famask <src.fa> <mask.fa>\n");
        return 1;
    }
    KseqLite src(argv[optind]);
    KseqLite mask(argv[optind + 1]);
    if (!src.is_open() || !mask.is_open()) {
        fprintf(stderr, "[E::stk_famask] failed to open the input file/stream.\n");
        return 1;
    }
    while (src.read() >= 0) {
        mask.read(); // return value deliberately ignored
        if (!mask.has_name) {
            // the reference compares against a NULL mask name here and
            // dies with SIGSEGV (empty or record-less mask file)
            fflush(nullptr);
            raise(SIGSEGV);
        }
        if (src.name != mask.name)
            fprintf(stderr, "[stk_famask] Different sequence names: %s != %s\n",
                    src.name.c_str(), mask.name.c_str());
        if (src.seq.size() != mask.seq.size()) {
            fprintf(stderr, "[stk_famask] Unequal sequence length: %ld != %ld\n",
                    (long)src.seq.size(), (long)mask.seq.size());
            if (mask.seq.size() < src.seq.size())
                src.seq.resize(mask.seq.size());
        }
        for (size_t i = 0; i < src.seq.size(); ++i) {
            char mc = mask.seq[i];
            if (mc == 'x') src.seq[i] = (char)tolower((unsigned char)src.seq[i]);
            else if (mc != 'X') src.seq[i] = mc;
        }
        fputc('>', stdout);
        fputs(src.name.c_str(), stdout);
        fputc('\n', stdout);
        for (size_t i = 0; i < src.seq.size(); i += 60) {
            size_t n = src.seq.size() - i < 60 ? src.seq.size() - i : 60;
            fwrite(src.seq.data() + i, 1, n, stdout);
            fputc('\n', stdout);
        }
    }
    return 0;
}

